package com.shelf.launcher.ui

import com.shelf.launcher.R

/*
 * GENERATED by tools/media_templates/covers.py from the template pack (C:\\Users\\User\\Downloads\\Templates, each console's
 * cover/ folder): the system's own cover frame (the printed border, with a see-through window for the game's art) and its
 * spine, at their real proportions. Pictures: res/drawable-nodpi/cov_front_*.webp, cov_spine_*.webp. Don't edit by hand.
 *
 * Update 125 (by hand): the pack's spine pictures are gone at your request (spineRes null; the spine's shape stays, it
 * sizes the shelf slots). Steam keeps its spine; Android games get Voltcap's own case (front band and spine). Your own
 * console spines go in CustomSpines (CoverCases.kt).
 */

/**
 * A console's cover template: the front frame, its width / height and the art window's bounds (fractions l, t, r, b),
 * and the spine picture with its own width / height (as drawn in the pack: a spine can be lying down).
 */
internal class CoverTpl(
    val frontRes: Int, val frontAspect: Float, val win: FloatArray,
    val spineRes: Int?, val spineAspect: Float
)

/** Update 169: one of Voltcap's own cases (Steam, Android), not a console's. */
internal fun CoverTpl.isOwn(): Boolean = frontRes == R.drawable.cov_front_steam || frontRes == R.drawable.cov_front_android

internal object MediaCovers {
    fun of(platform: String?): CoverTpl? = platform?.let { all[it] ?: byHand[it] }

    /** Update 166: Voltcap's own cases (Steam, Android): no real case to show instead, so they're always used. */
    private val OWN = setOf("Steam", "App", "Android")

    /** Update 166: [platform]'s case when it's one of Voltcap's own (Steam, Android), whatever the cover templates switch says. */
    fun own(platform: String?): CoverTpl? = platform?.takeIf { it in OWN }?.let { of(it) }

    /**
     * Update 166: the cover template to draw [platform]'s case with: Voltcap's own (Steam, Android) always — they were
     * plain covers with the cover templates off — the others with Settings › Cover templates on ([mixed]: not in a list
     * mixing consoles, as before).
     */
    fun used(platform: String?, mixed: Boolean = false): CoverTpl? =
        own(platform) ?: if (!mixed && com.shelf.launcher.data.Features.coverTemplates.state.value) of(platform) else null

    /** Update 129 (by hand): every console with a case here (R1 › Case tile). */
    fun keys(): List<String> = (all.keys + byHand.keys).toList()

